package it.financemanager.infrastructure.web;import it.financemanager.domain.model.*;import it.financemanager.infrastructure.web.dto.ApiDtos.*;final class WebMapper{static CategoryResponse category(Category c){return new CategoryResponse(c.id(),c.name(),c.color(),c.createdAt(),c.updatedAt());}static BudgetResponse budget(Budget b){return new BudgetResponse(b.id(),b.categoryId(),b.categoryName(),b.amount(),b.startDate(),b.endDate(),b.createdAt(),b.updatedAt());}static TransactionResponse transaction(Transaction t){return new TransactionResponse(t.id(),t.categoryId(),t.categoryName(),t.type(),t.amount(),t.date(),t.description(),t.createdAt(),t.updatedAt());}}
